package pe.fiberlux.nexus.service;
import pe.fiberlux.nexus.dao.Store;
import pe.fiberlux.nexus.model.Database;
import pe.fiberlux.nexus.model.Database.*;
import pe.fiberlux.nexus.util.*;
import java.time.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;
import static pe.fiberlux.nexus.service.Errors.require;

public final class TicketService{
 private final Store dao;private final SlaService sla=new SlaService();private final Path attachmentPath;
 public TicketService(Store dao,Path dataDir){this.dao=dao;attachmentPath=dataDir.resolve("attachments");}
 private boolean canSee(User actor,Ticket t){return actor.rol.equals("ADMINISTRADOR") || actor.rol.equals("CLIENTE")&&t.clienteId==actor.id || actor.rol.equals("TECNICO")&&(t.tecnicoId==actor.id||t.tecnicoId==0);}
 private User user(Database db,int id){return db.usuarios.get(id);}
 public Map<String,Object> dto(Database db,Ticket t){User c=user(db,t.clienteId),tech=user(db,t.tecnicoId);return M.of("id",t.id,"codigo",t.codigo,"titulo",t.titulo,"descripcion",t.descripcion,"categoria",t.categoria,"prioridad",t.prioridad,"estado",t.estado,"clienteId",t.clienteId,"cliente",c==null?"":c.empresa,"tecnicoId",t.tecnicoId,"tecnico",tech==null?"Sin asignar":tech.nombre,"creado",t.creado.toString(),"actualizado",t.actualizado.toString(),"resuelto",t.resuelto==null?null:t.resuelto.toString(),"cerrado",t.cerrado==null?null:t.cerrado.toString(),"conformidad",t.conformidad,"sede",t.sede,"enlace",t.enlace,"servicio",t.servicio,"sla",sla.status(t));}
 public List<Object> list(User actor,String search,String state,String priority,String category){return dao.read(db->{List<Ticket> ts=db.tickets.values().stream().filter(t->canSee(actor,t)).sorted(Comparator.comparing((Ticket t)->t.creado).reversed()).toList();List<Object> list=new ArrayList<>();for(Ticket t:ts){if(!state.isBlank()&&!state.equals("TODOS")&&!t.estado.equals(state))continue;if(!priority.isBlank()&&!priority.equals("TODOS")&&!t.prioridad.equals(priority))continue;if(!category.isBlank()&&!category.equals("TODAS")&&!t.categoria.equals(category))continue;String hay=(t.codigo+" "+t.titulo+" "+t.descripcion+" "+t.sede).toLowerCase(Locale.ROOT);if(!hay.contains(search.toLowerCase(Locale.ROOT)))continue;list.add(dto(db,t));}return list;});}
 public Map<String,Object> detail(User actor,int id){return dao.read(db->{Ticket t=lookup(db,id);require(canSee(actor,t),403,"Acceso denegado a este ticket");Map<String,Object> m=dto(db,t);List<Object> comments=new ArrayList<>(),audits=new ArrayList<>(),files=new ArrayList<>();for(Comment c:db.comentarios.values())if(c.ticketId==id&&(!c.interno||!actor.rol.equals("CLIENTE"))){User u=user(db,c.usuarioId);comments.add(M.of("id",c.id,"autor",u==null?"Sistema":u.nombre,"texto",c.texto,"interno",c.interno,"fecha",c.creado.toString()));}for(Audit a:db.auditorias.values())if(a.ticketId==id){User u=user(db,a.usuarioId);audits.add(M.of("accion",a.accion,"detalle",a.detalle,"autor",u==null?"Sistema":u.nombre,"fecha",a.creado.toString()));}for(Attachment a:db.adjuntos.values())if(a.ticketId==id)files.add(M.of("id",a.id,"nombre",a.nombre,"tamano",a.tamano,"mime",a.mime));m.put("comentarios",comments);m.put("auditoria",audits);m.put("adjuntos",files);return m;});}
 private Ticket lookup(Database db,int id){Ticket t=db.tickets.get(id);if(t==null)throw new Errors.HttpError(404,"Ticket no encontrado");return t;}
 private void audit(Database db,int ticket,int actor,String action,String detail){Audit a=new Audit();a.id=db.nextAudit++;a.ticketId=ticket;a.usuarioId=actor;a.accion=action;a.detalle=detail;a.creado=LocalDateTime.now();db.auditorias.put(a.id,a);}
 private int selectTechnician(Database db,String category){List<User> techs=db.usuarios.values().stream().filter(u->u.activo&&u.rol.equals("TECNICO")).toList();if(techs.isEmpty())return 0;return techs.stream().min(Comparator.comparingInt(u->(int)db.tickets.values().stream().filter(t->t.tecnicoId==u.id&&!List.of("CERRADO","RESUELTO").contains(t.estado)).count())).get().id;}
 public Map<String,Object> create(User actor,Map<String,Object> form){AuthService.role(actor,"CLIENTE","ADMINISTRADOR");String title=M.required(form,"titulo",150),description=M.required(form,"descripcion",4000);String priority=M.choice(Json.str(form,"prioridad"),"P1","P2","P3","P4"),category=M.choice(Json.str(form,"categoria"),"Fibra óptica","Latencia","CPE / Switch","Monitoreo","BGP / Enrutamiento","Otros");
 return dao.write(db->{int client=actor.rol.equals("CLIENTE")?actor.id:Json.integer(form,"clienteId");User c=db.usuarios.get(client);require(c!=null&&c.activo&&c.rol.equals("CLIENTE"),400,"Seleccione un cliente válido");Ticket t=new Ticket();t.id=db.nextTicket++;t.codigo="FLX-"+t.id;t.clienteId=client;t.prioridad=priority;t.categoria=category;t.titulo=title;t.descripcion=description;t.creado=LocalDateTime.now();t.actualizado=t.creado;t.sede=Integrations.clean(Json.str(form,"sede"));t.enlace=Integrations.clean(Json.str(form,"enlace"));t.servicio=Integrations.clean(Json.str(form,"servicio"));t.tecnicoId=selectTechnician(db,category);t.estado=t.tecnicoId!=0?"ASIGNADO":"ABIERTO";db.tickets.put(t.id,t);audit(db,t.id,actor.id,"CREACION","Ticket registrado (prioridad "+priority+")");if(t.tecnicoId!=0)audit(db,t.id,actor.id,"ASIGNACION","Asignación inicial automática al técnico #"+t.tecnicoId);return dto(db,t);});}
 public Map<String,Object> assign(User actor,int id,int tech){AuthService.role(actor,"ADMINISTRADOR");return dao.write(db->{Ticket t=lookup(db,id);require(!List.of("CERRADO","RESUELTO").contains(t.estado),409,"No se asignan tickets finalizados");User u=db.usuarios.get(tech);require(u!=null&&u.activo&&u.rol.equals("TECNICO"),400,"Técnico no disponible");t.tecnicoId=tech;t.estado="ASIGNADO";t.actualizado=LocalDateTime.now();audit(db,id,actor.id,"ASIGNACION","Asignado a "+u.nombre);return dto(db,t);});}
 public Map<String,Object> updateState(User actor,int id,String newState){AuthService.role(actor,"TECNICO","ADMINISTRADOR");M.choice(newState,"ASIGNADO","EN_PROCESO","ESCALADO","RESUELTO","CERRADO");return dao.write(db->{Ticket t=lookup(db,id);require(actor.rol.equals("ADMINISTRADOR")||actor.id==t.tecnicoId,403,"Solo el técnico asignado puede actualizar el ticket");require(!t.estado.equals("CERRADO"),409,"El ticket está cerrado");require(!newState.equals("CERRADO") || t.estado.equals("RESUELTO"),409,"Debe resolver antes de cerrar");if(newState.equals("RESUELTO"))t.resuelto=LocalDateTime.now();if(newState.equals("CERRADO"))t.cerrado=LocalDateTime.now();String old=t.estado;t.estado=newState;t.actualizado=LocalDateTime.now();audit(db,id,actor.id,"CAMBIO_ESTADO",old+" → "+newState);return dto(db,t);});}
 public Map<String,Object> conformity(User actor,int id){AuthService.role(actor,"CLIENTE","ADMINISTRADOR");return dao.write(db->{Ticket t=lookup(db,id);require(actor.rol.equals("ADMINISTRADOR")||actor.id==t.clienteId,403,"Este ticket pertenece a otro cliente");require(t.estado.equals("RESUELTO"),409,"Solo se puede confirmar un ticket resuelto");t.estado="CERRADO";t.conformidad=true;t.cerrado=LocalDateTime.now();t.actualizado=t.cerrado;audit(db,id,actor.id,"CONFORMIDAD","Cliente confirmó resolución y cierre");return dto(db,t);});}
 public Map<String,Object> comment(User actor,int id,Map<String,Object> data){String txt=M.required(data,"texto",2500);boolean internal=Json.bool(data,"interno");if(internal)require(!actor.rol.equals("CLIENTE"),403,"El cliente no puede crear notas internas");return dao.write(db->{Ticket t=lookup(db,id);require(canSee(actor,t),403,"Acceso denegado");require(!t.estado.equals("CERRADO"),409,"No se admiten comentarios en tickets cerrados");Comment c=new Comment();c.id=db.nextComment++;c.ticketId=id;c.usuarioId=actor.id;c.texto=txt;c.interno=internal;c.creado=LocalDateTime.now();db.comentarios.put(c.id,c);audit(db,id,actor.id,"COMENTARIO",internal?"Nota interna":"Comentario público");return M.of("id",c.id,"autor",actor.nombre,"texto",txt,"interno",internal,"fecha",c.creado.toString());});}
 public Map<String,Object> upload(User actor,int id,Map<String,Object> data){String name=M.required(data,"nombre",100),mime=M.choice(Json.str(data,"mime"),"image/png","image/jpeg","application/pdf","text/plain");String text=M.required(data,"base64",3_000_000);byte[] bytes;try{bytes=Base64.getDecoder().decode(text);}catch(IllegalArgumentException e){throw new Errors.HttpError(400,"Archivo codificado inválido");}require(bytes.length>0&&bytes.length<=2_000_000,400,"Adjunto máximo: 2 MB");require(!name.contains("/")&&!name.contains("\\")&&!name.contains(".."),400,"Nombre de archivo inválido");require((!mime.equals("image/png")||(bytes.length>4&&(bytes[0]&0xff)==0x89&&bytes[1]=='P'))&&(!mime.equals("application/pdf")||(bytes.length>4&&bytes[0]=='%'&&bytes[1]=='P')),400,"El contenido no coincide con el formato");
 try{Files.createDirectories(attachmentPath);}catch(Exception e){throw new IllegalStateException(e);}return dao.write(db->{Ticket t=lookup(db,id);require(canSee(actor,t),403,"Acceso denegado");Attachment a=new Attachment();a.id=db.nextAttachment++;a.ticketId=id;a.usuarioId=actor.id;a.nombre=name;a.mime=mime;a.tamano=bytes.length;a.creado=LocalDateTime.now();a.storedName=UUID.randomUUID().toString()+".bin";try{Files.write(attachmentPath.resolve(a.storedName),bytes,StandardOpenOption.CREATE_NEW);}catch(Exception ex){throw new IllegalStateException("No se pudo escribir adjunto",ex);}db.adjuntos.put(a.id,a);audit(db,id,actor.id,"ADJUNTO","Archivo "+name);return M.of("id",a.id,"nombre",a.nombre,"tamano",a.tamano);});}
 public byte[] attachment(User actor,int id){return dao.read(db->{Attachment a=db.adjuntos.get(id);require(a!=null,404,"Adjunto inexistente");Ticket t=lookup(db,a.ticketId);require(canSee(actor,t),403,"Acceso denegado");try{return Files.readAllBytes(attachmentPath.resolve(a.storedName));}catch(Exception ex){throw new IllegalStateException("Adjunto no disponible",ex);}});}
 public String mimeOf(int id){return dao.read(db->{Attachment a=db.adjuntos.get(id);return a==null?"application/octet-stream":a.mime;});}
 public List<Object> technicians(){return dao.read(db->{List<Object> l=new ArrayList<>();for(User u:db.usuarios.values())if(u.rol.equals("TECNICO")&&u.activo)l.add(AuthService.publicUser(u));return l;});}
 public List<Object> clients(){return dao.read(db->{List<Object> l=new ArrayList<>();for(User u:db.usuarios.values())if(u.rol.equals("CLIENTE")&&u.activo)l.add(AuthService.publicUser(u));return l;});}
 public List<Object> kanban(User actor){return list(actor,"","","","");}
}
